=== FILE: uart_tx_rootcause_tb.v ===
// Self-checking repro: an 8N1 UART transmitter must ignore a start pulse
// while a frame is in flight. Expected values come from the 8N1 contract,
// not from any implementation's output.
`timescale 1ns / 1ps
module uart_tx_rootcause_tb;
    localparam integer CPB = 4;

    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data = 8'd0;
    wire       tx;
    wire       busy;

    integer passed = 0;
    integer failed = 0;
    integer i;
    reg [7:0] rx;
    reg done = 1'b0;
    reg [8*64-1:0] nonce;

    uart_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data),
        .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    task check(input cond, input [8*48-1:0] what);
        begin
            if (cond) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("CHECK FAILED: %0s", what);
            end
        end
    endtask

    task verdict;
        begin
            if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        end
    endtask

    initial begin
        rx = 8'd0;
        // Reset, inputs driven on falling edges.
        repeat (4) @(negedge clk);
        rst = 1'b0;
        repeat (2) @(negedge clk);

        // Launch frame 8'hA5 (accepted on the next rising edge).
        data  = 8'hA5;
        start = 1'b1;
        @(negedge clk);
        start = 1'b0;
        data  = 8'h00;

        // Middle of the start bit.
        @(negedge clk);
        check(tx == 1'b0, "start bit is 0");

        for (i = 0; i < 8; i = i + 1) begin
            if (i == 1) begin
                // A start pulse with a different byte while busy: must be ignored.
                @(negedge clk);
                data  = 8'h3C;
                start = 1'b1;
                @(negedge clk);
                start = 1'b0;
                data  = 8'h00;
                repeat (2) @(negedge clk);
            end else begin
                repeat (CPB) @(negedge clk);
            end
            rx[i] = tx;
        end
        if (rx !== 8'hA5)
            $display("received byte %h, expected a5", rx);
        check(rx === 8'hA5, "received byte equals transmitted 8'hA5");

        repeat (CPB) @(negedge clk);
        check(tx == 1'b1, "stop bit is 1");

        // After the stop bit the transmitter must be idle.
        repeat (2 * CPB) @(negedge clk);
        check(tx == 1'b1 && busy == 1'b0, "idle high and not busy after frame");

        done = 1'b1;
        verdict;
        $finish;
    end

    initial begin
        #100000;
        if (!done) begin
            $display("CHECK FAILED: watchdog timeout");
            failed = failed + 1;
            verdict;
            $finish;
        end
    end
endmodule
=== END FILE ===
